#include <Servo.h>

// Создаем объекты для двух сервоприводов
Servo servoVertical;  // Синяя обводка (Вверх/Вниз)
Servo servoHorizontal;// Красная обводка (Влево/Вправо)

// Пины подключения
const int pinServoVert = 9;  // Пин для вертикального серво
const int pinServoHoriz = 10;// Пин для горизонтального серво
const int pinJoyX = A0;      // Пин X джойстика
const int pinJoyY = A1;      // Пин Y джойстика

// Переменные для хранения значений
int joyX;
int joyY;

// Переменные для углов сервоприводов
int angleVert;
int angleHoriz;

void setup() {
  // Подключаем сервоприводы к пинам
  servoVertical.attach(pinServoVert);
  servoHorizontal.attach(pinServoHoriz);

  // Инициализация Serial Monitor (для отладки, опционально)
  Serial.begin(9600);

  // Стартовое положение (ставим на середину, 90 градусов)
  servoVertical.write(90);
  servoHorizontal.write(90);

  delay(1000); // Даем время сервоприводам встать на место
}

void loop() {
  // 1. Считываем значения с джойстика (от 0 до 1023)
  joyX = analogRead(pinJoyX); 
  joyY = analogRead(pinJoyY);

  // 2. Преобразуем значения. 
  // Джойстик в центре выдает ~512. Нам нужно преобразовать 0-1023 в 0-180 (градусы).
  // Используем функцию map и constrain (ограничиваем, чтобы не вылететь за пределы)

  // Для вертикального серво (Вверх/Вниз) берем ось Y
  angleVert = map(joyY, 0, 1023, 0, 180);
  angleVert = constrain(angleVert, 0, 180);

  // Для горизонтального серво (Влево/Вправо) берем ось X
  angleHoriz = map(joyX, 0, 1023, 0, 180);
  angleHoriz = constrain(angleHoriz, 0, 180);

  // 3. Подаем команды сервоприводам
  servoVertical.write(angleVert);
  servoHorizontal.write(angleHoriz);

  // Вывод в монитор порта для проверки (опционально)
  Serial.print("X: ");
  Serial.print(joyX);
  Serial.print(" | Y: ");
  Serial.print(joyY);
  Serial.print(" | Servo V: ");
  Serial.print(angleVert);
  Serial.print(" | Servo H: ");
  Serial.println(angleHoriz);

  // Небольшая задержка, чтобы сервоприводы успевали двигаться плавно
  delay(15); 
}
